// substitute rebuilds a request path from a route pattern and params.
func substitute(fullPath string, ps Params) (string, bool) {
	var sb strings.Builder
	pi := 0
	i := 0
	for i < len(fullPath) {
		c := fullPath[i]
		if c == ':' || c == '*' {
			j := i + 1
			for j < len(fullPath) && fullPath[j] != '/' {
				j++
			}
			if pi >= len(ps) {
				return "", false
			}
			if c == '*' {
				// catch-all value includes the leading '/'
				s := sb.String()
				if strings.HasSuffix(s, "/") {
					sb.Reset()
					sb.WriteString(s[:len(s)-1])
				}
			}
			sb.WriteString(ps[pi].Value)
			pi++
			i = j
			continue
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String(), pi == len(ps)
}

