func zzGenRoute(rnd *rand.Rand, i int) string {
	lits := []string{"a", "b", "c", "ab", "abc", "x", "y", "z", "aa", "bc"}
	n := 1 + rnd.Intn(4)
	var sb strings.Builder
	for s := 0; s < n; s++ {
		sb.WriteByte('/')
		switch k := rnd.Intn(4); k {
		case 0:
			sb.WriteString(":" + string(rune('p'+rnd.Intn(3))))
		case 1:
			if s == n-1 {
				sb.WriteString("*" + string(rune('c'+rnd.Intn(2))))
			} else {
				sb.WriteString(lits[rnd.Intn(len(lits))])
			}
		default:
			sb.WriteString(lits[rnd.Intn(len(lits))])
		}
	}
	if rnd.Intn(4) == 0 {
		sb.WriteByte('/')
	}
	return sb.String()
}

